<?php
require __DIR__.'/config.php'; $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if(!$name){flash('Supplier name is required.','error');redirect('suppliers.php');}$v=[$name,trim($_POST['contact_person']??''),trim($_POST['phone']??''),trim($_POST['email']??''),trim($_POST['address']??''),trim($_POST['gstin']??'')];if($id){$v[]=$id;$pdo->prepare('UPDATE suppliers SET name=?,contact_person=?,phone=?,email=?,address=?,gstin=? WHERE id=?')->execute($v);flash('Supplier details updated.');}else{$pdo->prepare('INSERT INTO suppliers(name,contact_person,phone,email,address,gstin) VALUES(?,?,?,?,?,?)')->execute($v);flash('Supplier added.');}redirect('suppliers.php');}
if(isset($_GET['delete'])){$pdo->prepare('UPDATE suppliers SET active=0 WHERE id=?')->execute([(int)$_GET['delete']]);flash('Supplier archived.');redirect('suppliers.php');}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM suppliers WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$suppliers=$pdo->query('SELECT s.*,COUNT(m.id) medicine_count FROM suppliers s LEFT JOIN medicines m ON m.supplier_id=s.id AND m.active=1 WHERE s.active=1 GROUP BY s.id ORDER BY s.name')->fetchAll();$pageTitle='Suppliers';require __DIR__.'/partials/header.php';
?>
<div class="welcome"><div><div class="eyebrow">PARTNERS</div><h1>Supplier directory</h1><p>Supplier contacts and linked catalogue items, all in one place.</p></div><button class="button" onclick="document.getElementById('supplier-form').scrollIntoView({behavior:'smooth'})">＋ Add supplier</button></div>
<section class="panel form-panel" id="supplier-form"><div class="panel-heading"><div><div class="eyebrow"><?= $edit?'EDIT PARTNER':'NEW PARTNER' ?></div><h2><?= $edit?'Update supplier':'Add a supplier' ?></h2></div></div><form method="post" class="form-grid"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Company name *<input required name="name" value="<?= h($edit['name']??'') ?>" placeholder="Supplier or distributor"></label><label>Contact person<input name="contact_person" value="<?= h($edit['contact_person']??'') ?>" placeholder="Full name"></label><label>Phone<input name="phone" value="<?= h($edit['phone']??'') ?>" placeholder="+91 98765 43210"></label><label>Email<input type="email" name="email" value="<?= h($edit['email']??'') ?>" placeholder="name@company.in"></label><label>GSTIN<input name="gstin" value="<?= h($edit['gstin']??'') ?>" placeholder="GST identification number"></label><label>Address<input name="address" value="<?= h($edit['address']??'') ?>" placeholder="Business address"></label><div class="form-actions"><button class="button"><?= $edit?'Save changes':'Add supplier' ?></button><?php if($edit): ?><a class="button secondary" href="suppliers.php">Cancel</a><?php endif; ?></div></form></section>
<section class="supplier-grid"><?php foreach($suppliers as $s): ?><article class="panel supplier-card"><div class="supplier-card-head"><div class="supplier-symbol">♙</div><div class="row-actions"><a href="?edit=<?= $s['id'] ?>">Edit</a><a class="danger-link" href="?delete=<?= $s['id'] ?>" data-confirm="Archive this supplier?">Archive</a></div></div><h2><?= h($s['name']) ?></h2><p class="supplier-person"><?= h($s['contact_person']?:'Supplier partner') ?></p><div class="supplier-info"><?php if($s['phone']): ?><a href="tel:<?= h($s['phone']) ?>">☎ &nbsp;<?= h($s['phone']) ?></a><?php endif; ?><?php if($s['email']): ?><a href="mailto:<?= h($s['email']) ?>">✉ &nbsp;<?= h($s['email']) ?></a><?php endif; ?><?php if($s['address']): ?><span>⌖ &nbsp;<?= h($s['address']) ?></span><?php endif; ?><?php if($s['gstin']): ?><span>GSTIN &nbsp;<?= h($s['gstin']) ?></span><?php endif; ?></div><div class="supplier-foot"><span>Linked medicines</span><b><?= (int)$s['medicine_count'] ?></b></div></article><?php endforeach; ?><?php if(!$suppliers): ?><div class="panel empty">No suppliers yet. Add your first distribution partner above.</div><?php endif; ?></section>
<?php require __DIR__.'/partials/footer.php'; ?>
